void flash(int which) {                 // 0 = red (button 1), 1 = green (button 2)
  int led = which == 0 ? RED_LED : GREEN_LED;
  digitalWrite(led, HIGH);
  tone(PIEZO, which == 0 ? 330 : 523, 250);
  delay(300);
  digitalWrite(led, LOW);
