int waitInput() {
  while (true) {
    if (digitalRead(BTN1) == LOW) { while (digitalRead(BTN1) == LOW) { } delay(30); return 0; }
    if (digitalRead(BTN2) == LOW) { while (digitalRead(BTN2) == LOW) { } delay(30); return 1; }
  }
}

void setup() {
