  Serial.println("Simon: watch, then repeat. Red button = red, black button = green.");
  delay(1500);
}

void loop() {
  seq[level] = random(0, 2);
  level++;
  setRGB(0, 0, 40 + level * 10);        // blue grows brighter with each level
  for (int i = 0; i < level; i++) flash(seq[i]);
  Serial.print("Level "); Serial.println(level);
  for (int i = 0; i < level; i++) {
    int pressed = waitInput();
    flash(pressed);
    if (pressed != seq[i]) {
      Serial.print("Wrong! You reached level "); Serial.println(level - 1);
      setRGB(255, 0, 0);
      tone(PIEZO, 120, 800);
      delay(1500);
      level = 0;
      return;
