}

void loop() {
  if (pressed()) {
    override = (override + 1) % 3;
    Serial.println(override == 0 ? "AUTO" : (override == 1 ? "FORCE ON" : "FORCE OFF"));
  }
  int dark = analogRead(LDR);
  int threshold = map(analogRead(POT), 0, 1023, 300, 800);
  if (!night && dark > threshold + 30) { night = true; Serial.println("Night - lamp fading in"); }
  if (night && dark < threshold - 30) { night = false; Serial.println("Day - lamp fading out"); }

  bool want = (override == 0) ? night : (override == 1);
  float target = want ? 1.0 : 0.0;
  level += (target - level) * 0.03;                  // smooth fade
  setRGB(level * 255, level * 150, level * 40);      // warm white
  delay(20);
}

