void colourFor(int n) {
  int seg = n % 7;
  int r = 0, g = 0, b = 0;
  if (seg == 0) { r = 255; }
  else if (seg == 1) { r = 255; g = 120; }
  else if (seg == 2) { r = 255; g = 255; }
  else if (seg == 3) { g = 255; }
  else if (seg == 4) { g = 255; b = 255; }
  else if (seg == 5) { b = 255; }
  else { r = 200; b = 255; }
  if (n >= 7) { r = r / 2; g = g / 2; b = b / 2; }       // higher octave dimmer
  setRGB(r, g, b);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
