  int n = map(analogRead(POT), 0, 1023, 0, 13);
  colourFor(n);
  if (n != lastNote) { lastNote = n; Serial.println(names.substring(n * 2, n * 2 + 2)); }
  if (digitalRead(BTN1) == LOW) tone(PIEZO, scale[n]);
  else noTone(PIEZO);
