  }
  if (tripped) {
    digitalWrite(BUZZER, (millis() / 150) % 2);
    digitalWrite(RED_LED, (millis() / 150) % 2);
    if (!armed && digitalRead(BTN1) == LOW) {          // disarm switch + button = reset
      tripped = false;
      digitalWrite(BUZZER, LOW); digitalWrite(RED_LED, LOW);
      Serial.println("Alarm reset");
    }
  } else {
    digitalWrite(BUZZER, LOW);
    digitalWrite(RED_LED, LOW);
