enum { IDLE, COINS, DISPENSE, REFUND };
int state = IDLE;
int coins = 0;
int price = 3;
int lastBtn = HIGH;
unsigned long since = 0;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("Vending demo: pot = item price (1-5), button = insert a coin");
}

void loop() {
  price = map(analogRead(POT), 0, 1023, 1, 5);
  int b = digitalRead(BTN1);
  bool coin = (lastBtn == HIGH && b == LOW);
  lastBtn = b;
  if (coin) delay(30);

  if (state == IDLE || state == COINS) {
    if (coin) {
      coins++; since = millis(); state = COINS;
      tone(PIEZO, 880, 80);
      Serial.print("coins "); Serial.print(coins); Serial.print(" / price "); Serial.println(price);
    }
    if (state == COINS && coins >= price) { state = DISPENSE; since = millis(); Serial.println("Dispensing item"); }
    else if (state == COINS && millis() - since > 6000) { state = REFUND; since = millis(); Serial.println("Timeout - refund"); }
  }
  if (state == DISPENSE) {
    digitalWrite(GREEN_LED, (millis() / 150) % 2);
    if (millis() - since > 1500) {
      digitalWrite(GREEN_LED, LOW);
      int change = coins - price;
      coins = 0;
      if (change > 0) { Serial.print("Change: "); Serial.println(change); state = REFUND; since = millis(); coins = change; }
      else state = IDLE;
    }
  }
  if (state == REFUND) {
    digitalWrite(RED_LED, (millis() / 150) % 2);
    if (millis() - since > 1200) { digitalWrite(RED_LED, LOW); coins = 0; state = IDLE; Serial.println("Ready"); }
  }
}

// ---- Circuit (Kit 1) ----
// 10k pot: ends to 5V and GND, wiper -> A0
// Passive piezo + -> D8, - -> GND
// RGB LED (common cathode -> GND): R-220-D9, G-220-D10, B-220-D11
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define POT A0
#define PIEZO 8
#define RGB_R 9
#define RGB_G 10
#define RGB_B 11
#define BTN1 2

#include <EEPROM.h>
void setRGB(int r, int g, int b) {
  analogWrite(RGB_R, r);
  analogWrite(RGB_G, g);
  analogWrite(RGB_B, b);
}

int bpm = 100;
int beat = 0;
unsigned long next = 0;
int lastShown = 0;
int lastBtn = HIGH;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
  int saved = EEPROM.read(0);
  if (saved >= 40 && saved <= 208) Serial.print("Saved tempo: ");
  if (saved >= 40 && saved <= 208) Serial.println(saved);
  Serial.println("Pot = tempo, button = save tempo");
}

void loop() {
  bpm = map(analogRead(POT), 0, 1023, 40, 208);
  if (abs(bpm - lastShown) >= 3) { lastShown = bpm; Serial.print("BPM "); Serial.println(bpm); }

  int b = digitalRead(BTN1);
  if (lastBtn == HIGH && b == LOW) { EEPROM.write(0, bpm); Serial.print("Saved "); Serial.println(bpm); delay(30); }
  lastBtn = b;

  if (millis() >= next) {
    next = millis() + 60000UL / bpm;
    bool accent = (beat % 4 == 0);
    tone(PIEZO, accent ? 1200 : 800, 40);
    if (accent) setRGB(255, 0, 0); else setRGB(0, 0, 255);
    beat++;
  }
  if (millis() > next - 60000UL / bpm + 70) setRGB(0, 0, 0);       // flash lasts ~70 ms
}

// ---- Circuit (Kit 1) ----
// Red LED anode -> 220 ohm -> D3 (PWM), cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// RGB LED (common cathode -> GND): R-220-D9, G-220-D10, B-220-D11
// Slide switch COM -> D7, one side -> GND (INPUT_PULLUP: LOW = side 1, HIGH = side 2)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define RED_LED 3
#define GREEN_LED 5
#define RGB_R 9
#define RGB_G 10
#define RGB_B 11
#define SLIDE 7
#define BTN1 2

bool pressedLast = HIGH;
bool pressed() {
  bool now = digitalRead(BTN1);
  bool hit = (pressedLast == HIGH && now == LOW);
  pressedLast = now;
  if (hit) delay(25);
  return hit;
}
int count = 0;

int toGray(int n) { return n ^ (n >> 1); }

void show() {
  int code = (digitalRead(SLIDE) == LOW) ? count : toGray(count);
  digitalWrite(RED_LED, code & 1);
  digitalWrite(GREEN_LED, (code >> 1) & 1);
  digitalWrite(RGB_R, (code >> 2) & 1);
  digitalWrite(RGB_G, (code >> 3) & 1);
  Serial.print(digitalRead(SLIDE) == LOW ? "binary " : "gray   ");
  Serial.print(count);
  Serial.print(" -> ");
  for (int i = 3; i >= 0; i--) Serial.print((code >> i) & 1);
  Serial.println();
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(SLIDE, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
  Serial.println("Button = count up, slide switch = binary / Gray code");
  show();
}

void loop() {
  if (pressed()) { count = (count + 1) % 16; show(); }
}

