enum { NONE, CLICK, DOUBLE, LONGPRESS };
int palette[6][3] = {{255,0,0},{255,120,0},{0,255,0},{0,255,255},{0,0,255},{255,0,255}};
int colour = 0;
int brightness = 255;
bool lampOn = true;

// ---- tiny button library: returns an event once per gesture
bool pressedNow = false;
unsigned long downAt = 0, upAt = 0;
int clicks = 0;
int poll() {
  bool down = (digitalRead(BTN1) == LOW);
  unsigned long now = millis();
  if (down && !pressedNow) { pressedNow = true; downAt = now; }
  if (!down && pressedNow) {
    pressedNow = false;
    if (now - downAt > 30) {
      if (now - downAt >= 700) { clicks = 0; return LONGPRESS; }
      clicks++; upAt = now;
    }
  }
  if (clicks > 0 && !pressedNow && now - upAt > 300) {
    int c = clicks; clicks = 0;
    return c >= 2 ? DOUBLE : CLICK;
  }
  return NONE;
}

void render() {
  if (!lampOn) { setRGB(0, 0, 0); return; }
  setRGB(palette[colour][0] * brightness / 255, palette[colour][1] * brightness / 255, palette[colour][2] * brightness / 255);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
  Serial.println("click = next colour | double-click = on/off | long press = brightness");
  render();
}

void loop() {
  int e = poll();
  if (e == CLICK) { colour = (colour + 1) % 6; Serial.println("click"); }
  if (e == DOUBLE) { lampOn = !lampOn; Serial.println("double-click"); }
  if (e == LONGPRESS) { brightness = (brightness > 70) ? brightness - 90 : 255; Serial.print("long press, brightness "); Serial.println(brightness); }
  if (e != NONE) render();
}

// ---- Circuit (Kit 1) ----
// LDR module: VCC -> 5V, GND -> GND, AO -> A1 (bright = low reading, dark = high)
// Active buzzer + -> D12, - -> GND
// Red LED anode -> 220 ohm -> D3 (PWM), cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define LDR A1
#define BUZZER 12
#define RED_LED 3
#define GREEN_LED 5
#define BTN1 2

float baseline = 800;      // slow-moving average of the ambient level
int events = 0;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT); pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  baseline = analogRead(LDR);
  Serial.println("Armed. Light flashes (LDR 'light level' slider) are logged. Button prints summary.");
}

void loop() {
  int v = analogRead(LDR);
  int jump = baseline - v;                   // positive = suddenly brighter
  digitalWrite(GREEN_LED, (millis() / 1000) % 2);     // heartbeat = monitoring
  if (jump > 120) {
    events++;
    int severity = jump > 400 ? 3 : (jump > 250 ? 2 : 1);
    Serial.print("["); Serial.print(millis() / 1000); Serial.print(" s] flash #"); Serial.print(events);
    Serial.print(" severity "); Serial.println(severity);
    for (int i = 0; i < severity; i++) {
      digitalWrite(BUZZER, HIGH); digitalWrite(RED_LED, HIGH); delay(120);
      digitalWrite(BUZZER, LOW); digitalWrite(RED_LED, LOW); delay(120);
    }
    delay(1500);
    baseline = analogRead(LDR);
  } else {
    baseline = baseline * 0.98 + v * 0.02;
  }
  if (digitalRead(BTN1) == LOW) {
    Serial.print("Summary: "); Serial.print(events); Serial.println(" events");
    delay(500);
  }
  delay(40);
}

// ---- Circuit (Kit 1) ----
// 10k pot: ends to 5V and GND, wiper -> A0
// Passive piezo + -> D8, - -> GND
// LDR module: VCC -> 5V, GND -> GND, AO -> A1 (bright = low reading, dark = high)
#define POT A0
#define PIEZO 8
#define LDR A1

int lastCode = -1;

void setup() {
  Serial.begin(9600);
}

void sendCode(int code) {
  for (int i = 3; i >= 0; i--) {
    int bit = (code >> i) & 1;
    tone(PIEZO, bit ? 1500 : 600, 120);       // 1 = high tone, 0 = low tone
    delay(180);
  }
}

void loop() {
  int pot = analogRead(POT);
  int code = pot / 64;                          // 0..15
  Serial.print("pot:"); Serial.print(pot);
  Serial.print(" code:"); Serial.print(code * 64);
  Serial.print(" light:"); Serial.println(1023 - analogRead(LDR));
  if (code != lastCode) {
    lastCode = code;
    sendCode(code);
  }
  delay(100);
}

// ---- Circuit (Kit 1) ----
// RGB LED (common cathode -> GND): R-220-D9, G-220-D10, B-220-D11
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// 10k pot: ends to 5V and GND, wiper -> A0
// Slide switch COM -> D7, one side -> GND (INPUT_PULLUP: LOW = side 1, HIGH = side 2)
// Passive piezo + -> D8, - -> GND
#define RGB_R 9
#define RGB_G 10
#define RGB_B 11
#define BTN1 2
#define POT A0
#define SLIDE 7
#define PIEZO 8

void setRGB(int r, int g, int b) {
  analogWrite(RGB_R, r);
  analogWrite(RGB_G, g);
  analogWrite(RGB_B, b);
}
bool pressedLast = HIGH;
bool pressed() {
  bool now = digitalRead(BTN1);
  bool hit = (pressedLast == HIGH && now == LOW);
  pressedLast = now;
  if (hit) delay(25);
  return hit;
}

int scene = 0;
unsigned long since = 0;
unsigned long flashAt = 0;
bool flash = false;

void render(int s, int bright) {
  int r = 0, g = 0, b = 0;
  if (s == 0) { r = 255; g = 160; b = 60; }         // dawn
  else if (s == 1) { r = 20; g = 200; b = 60; }      // forest
  else if (s == 2) { r = 255; g = 70; b = 10; }      // sunset
  else {                                             // storm: dark blue with lightning
    r = 10; g = 10; b = 90;
    if (flash) { r = 255; g = 255; b = 255; }
  }
  setRGB(r * bright / 255, g * bright / 255, b * bright / 255);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(SLIDE, INPUT_PULLUP);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
  Serial.println("Story lamp: button = next scene, slide HIGH = auto advance, pot = brightness");
}

void next() {
  scene = (scene + 1) % 4;
  since = millis();
  tone(PIEZO, 400 + scene * 150, 120);
  Serial.print("Scene "); Serial.println(scene);
}

void loop() {
  if (pressed()) next();
  if (digitalRead(SLIDE) == HIGH && millis() - since > 5000) next();
  if (scene == 3 && millis() > flashAt) {            // random lightning
    flash = !flash;
    flashAt = millis() + (flash ? 60 : random(400, 2500));
  }
  render(scene, map(analogRead(POT), 0, 1023, 20, 255));
  delay(10);
}

// ---- Circuit (Kit 1) ----
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Second push button between D4 and GND (INPUT_PULLUP)
// Red LED anode -> 220 ohm -> D3 (PWM), cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Active buzzer + -> D12, - -> GND
#define BTN1 2
#define BTN2 4
#define RED_LED 3
#define GREEN_LED 5
#define BUZZER 12

int score1 = 0, score2 = 0;

void winner(int p) {
  if (p == 1) { digitalWrite(RED_LED, HIGH); score1++; } else { digitalWrite(GREEN_LED, HIGH); score2++; }
  Serial.print("Player "); Serial.print(p); Serial.println(" wins the round!");
  Serial.print("Score  P1 "); Serial.print(score1); Serial.print(" : "); Serial.print(score2); Serial.println(" P2");
  delay(1500);
  digitalWrite(RED_LED, LOW); digitalWrite(GREEN_LED, LOW);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP); pinMode(BTN2, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT); pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  Serial.println("Quick draw! Wait for the BEEP, then hit your button first.");
}

void loop() {
  delay(1500);
  Serial.println("Ready...");
  unsigned long wait = random(1500, 4500);
  unsigned long t0 = millis();
  while (millis() - t0 < wait) {
    if (digitalRead(BTN1) == LOW) { Serial.println("P1 jumped the gun!"); winner(2); return; }
    if (digitalRead(BTN2) == LOW) { Serial.println("P2 jumped the gun!"); winner(1); return; }
  }
  digitalWrite(BUZZER, HIGH);
  while (true) {
    if (digitalRead(BTN1) == LOW) { digitalWrite(BUZZER, LOW); winner(1); return; }
    if (digitalRead(BTN2) == LOW) { digitalWrite(BUZZER, LOW); winner(2); return; }
  }
}

// ---- Circuit (Kit 1) ----
// RGB LED (common cathode -> GND): R-220-D9, G-220-D10, B-220-D11
// Active buzzer + -> D12, - -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// 10k pot: ends to 5V and GND, wiper -> A0
#define RGB_R 9
#define RGB_G 10
#define RGB_B 11
#define BUZZER 12
#define BTN1 2
#define POT A0

void setRGB(int r, int g, int b) {
  analogWrite(RGB_R, r);
  analogWrite(RGB_G, g);
  analogWrite(RGB_B, b);
}
bool pressedLast = HIGH;
bool pressed() {
  bool now = digitalRead(BTN1);
  bool hit = (pressedLast == HIGH && now == LOW);
  pressedLast = now;
  if (hit) delay(25);
  return hit;
}

enum { WAITING, RISING, RINGING };
int state = WAITING;
unsigned long since = 0;
unsigned long riseMs = 20000;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
  Serial.println("Pot sets sunrise duration (10-60 s). Press the button to start the sunrise.");
}

void loop() {
  if (state == WAITING) {
    setRGB(0, 0, 0);
    if (pressed()) {
      riseMs = map(analogRead(POT), 0, 1023, 10, 60) * 1000UL;
      state = RISING; since = millis();
      Serial.print("Sunrise started, "); Serial.print(riseMs / 1000); Serial.println(" s");
    }
  } else if (state == RISING) {
    float p = (float)(millis() - since) / riseMs;       // 0..1
    if (p >= 1.0) { state = RINGING; since = millis(); Serial.println("GOOD MORNING!"); return; }
    setRGB(255 * p, 140 * p * p, 40 * p * p * p);       // red -> orange -> warm white
    if (pressed()) { state = WAITING; Serial.println("cancelled"); }
  } else {
    setRGB(255, 200, 120);
    digitalWrite(BUZZER, (millis() / 300) % 2);
    if (pressed()) {
      digitalWrite(BUZZER, LOW);
      state = WAITING;
      Serial.println("stopped");
    }
  }
}

// ---- Circuit (Kit 1) ----
// LDR module: VCC -> 5V, GND -> GND, AO -> A1 (bright = low reading, dark = high)
// Red LED anode -> 220 ohm -> D3 (PWM), cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define LDR A1
#define RED_LED 3
#define GREEN_LED 5
#define BTN1 2

int lo = 1023, hi = 0;
bool calibrating = true;
unsigned long calStart = 0;

void startCal() {
  lo = 1023; hi = 0; calibrating = true; calStart = millis();
  Serial.println("Calibrating for 5 s: move the LDR light slider from dark to bright...");
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  startCal();
}

void loop() {
  int v = 1023 - analogRead(LDR);                // convert to "brightness"
  if (calibrating) {
    if (v < lo) lo = v;
    if (v > hi) hi = v;
    digitalWrite(RED_LED, (millis() / 200) % 2);
    digitalWrite(GREEN_LED, (millis() / 200) % 2);
    if (millis() - calStart > 5000) {
      calibrating = false;
      digitalWrite(RED_LED, LOW); digitalWrite(GREEN_LED, LOW);
      Serial.print("Range "); Serial.print(lo); Serial.print(" .. "); Serial.println(hi);
    }
  } else {
    int pct = 0;
    if (hi > lo) pct = constrain(map(v, lo, hi, 0, 100), 0, 100);
    digitalWrite(RED_LED, pct > 33);
    digitalWrite(GREEN_LED, pct > 66);
    Serial.print("light "); Serial.print(pct); Serial.println("%");
    if (digitalRead(BTN1) == LOW) { startCal(); delay(300); }
  }
  delay(150);
}

// ---- Circuit (Kit 1) ----
// Slide switch COM -> D7, one side -> GND (INPUT_PULLUP: LOW = side 1, HIGH = side 2)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Red LED anode -> 220 ohm -> D3 (PWM), cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// RGB LED (common cathode -> GND): R-220-D9, G-220-D10, B-220-D11
#define SLIDE 7
#define BTN1 2
#define RED_LED 3
#define GREEN_LED 5
#define RGB_R 9
#define RGB_G 10
#define RGB_B 11

void setRGB(int r, int g, int b) {
  analogWrite(RGB_R, r);
  analogWrite(RGB_G, g);
  analogWrite(RGB_B, b);
}
bool pressedLast = HIGH;
bool pressed() {
  bool now = digitalRead(BTN1);
  bool hit = (pressedLast == HIGH && now == LOW);
  pressedLast = now;
  if (hit) delay(25);
  return hit;
}

int mode = 0;
int phase = 0;
unsigned long last = 0;

void blinkMode(int n) {                    // announce the mode with n red blinks
  for (int i = 0; i < n; i++) {
    digitalWrite(RED_LED, HIGH); delay(150);
    digitalWrite(RED_LED, LOW); delay(150);
  }
}

void allOff() {
  digitalWrite(RED_LED, LOW); digitalWrite(GREEN_LED, LOW); setRGB(0, 0, 0);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP); pinMode(SLIDE, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
  Serial.println("Button = next program, slide switch = speed");
  blinkMode(1);
}

void loop() {
  if (pressed()) {
    mode = (mode + 1) % 3;
    allOff();
    Serial.print("Program "); Serial.println(mode + 1);
    blinkMode(mode + 1);
    phase = 0;
  }
  int step = (digitalRead(SLIDE) == LOW) ? 400 : 120;
  if (millis() - last >= step) {
    last = millis();
    phase++;
    if (mode == 0) {                                   // alternate
      digitalWrite(RED_LED, phase % 2); digitalWrite(GREEN_LED, (phase + 1) % 2);
    } else if (mode == 1) {                            // colour fade steps
      int c = phase % 6;
      if (c == 0) setRGB(255, 0, 0); else if (c == 1) setRGB(255, 160, 0); else if (c == 2) setRGB(0, 255, 0);
      else if (c == 3) setRGB(0, 255, 255); else if (c == 4) setRGB(0, 0, 255); else setRGB(255, 0, 255);
    } else {                                           // chaser across 4 outputs
      int c = phase % 4;
      digitalWrite(RED_LED, c == 0); digitalWrite(GREEN_LED, c == 1);
      setRGB(c == 2 ? 255 : 0, 0, c == 3 ? 255 : 0);
    }
  }
}

// ---- Circuit (Kit 1) ----
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Slide switch COM -> D7, one side -> GND (INPUT_PULLUP: LOW = side 1, HIGH = side 2)
// RGB LED (common cathode -> GND): R-220-D9, G-220-D10, B-220-D11
// Active buzzer + -> D12, - -> GND
#define BTN1 2
#define SLIDE 7
#define RGB_R 9
#define RGB_G 10
#define RGB_B 11
#define BUZZER 12

void setRGB(int r, int g, int b) {
  analogWrite(RGB_R, r);
  analogWrite(RGB_G, g);
  analogWrite(RGB_B, b);
}

enum { DISARMED, EXIT_DELAY, ARMED, ENTRY_DELAY, ALARM };
int state = DISARMED;
unsigned long since = 0;
unsigned long downAt = 0;
bool btnDown = false;

bool longPress() {                            // true once when a 1.2 s press completes
  bool d = (digitalRead(BTN1) == LOW);
  if (d && !btnDown) { btnDown = true; downAt = millis(); }
  if (!d) btnDown = false;
  if (btnDown && millis() - downAt >= 1200) { btnDown = false; downAt = millis(); while (digitalRead(BTN1) == LOW) { } return true; }
  return false;
}

void go(int s, String msg) {
  state = s; since = millis();
  Serial.println(msg);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP); pinMode(SLIDE, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  pinMode(RGB_R, OUTPUT); pinMode(RGB_G, OUTPUT); pinMode(RGB_B, OUTPUT);
  Serial.begin(9600);
  Serial.println("Hold button 1.2 s = arm / disarm. Slide switch HIGH = door open.");
  setRGB(0, 255, 0);
}

void loop() {
  bool doorOpen = (digitalRead(SLIDE) == HIGH);
  bool hold = longPress();
  bool blink = (millis() / 250) % 2;

  if (state == DISARMED) {
    setRGB(0, 255, 0);
    if (hold) go(EXIT_DELAY, "Arming - leave now (5 s)");
  } else if (state == EXIT_DELAY) {
    if (blink) setRGB(255, 120, 0); else setRGB(0, 0, 0);
    if (hold) go(DISARMED, "Disarmed");
    else if (millis() - since > 5000) go(ARMED, "ARMED");
  } else if (state == ARMED) {
    setRGB(0, 0, 255);
    if (hold) go(DISARMED, "Disarmed");
    else if (doorOpen) go(ENTRY_DELAY, "Door opened! Disarm within 5 s");
  } else if (state == ENTRY_DELAY) {
    if (blink) setRGB(255, 120, 0); else setRGB(0, 0, 0);
    digitalWrite(BUZZER, (millis() / 500) % 2);
    if (hold) { digitalWrite(BUZZER, LOW); go(DISARMED, "Disarmed"); }
    else if (millis() - since > 5000) go(ALARM, "ALARM!");
  } else {
    digitalWrite(BUZZER, blink);
    if (blink) setRGB(255, 0, 0); else setRGB(0, 0, 0);
    if (hold) { digitalWrite(BUZZER, LOW); go(DISARMED, "Alarm cleared - disarmed"); }
  }
}
